{
  "manifest_version": 3,
  "name": "Store Price Personalizer (opt-in)",
  "version": "1.0",
  "description": "Optional: let users share their Amazon profile and show adjusted store prices based on inferred attributes.",
  "permissions": [
    "storage",
    "scripting",
    "tabs"
  ],
  "host_permissions": [
    "https://www.amazon.com/*",
    "https://www.amazon.*/*",
    "https://your-store.example/*"
  ],
  "action": {
    "default_popup": "popup.html"
  },
  "background": {
    "service_worker": "service_worker.js"
  },
  "content_scripts": [
    {
      "matches": ["https://www.amazon.com/*", "https://www.amazon.*/*"],
      "js": ["amazon_content.js"],
      "run_at": "document_idle"
    },
    {
      "matches": ["https://your-store.example/*"],
      "js": ["store_content.js"],
      "run_at": "document_idle"
    }
  ]
}

Replace "https://your-store.example/*" with your online store domain(s).

