popup.js
document.addEventListener("DOMContentLoaded", async () => {
  const status = document.getElementById("status");
  const openBtn = document.getElementById("open-amazon");
  const gCB = document.getElementById("enableGender");
  const iCB = document.getElementById("enableIncome");
  const eCB = document.getElementById("enableEthnicity");

  // load settings
  const { settings = {} } = await chrome.storage.local.get("settings");
  gCB.checked = !!settings.useGender;
  iCB.checked = !!settings.useIncome;
  eCB.checked = !!settings.useEthnicity;

  // show profile if available
  const res = await chrome.storage.local.get("userProfile");
  if (res.userProfile) {
    status.textContent = `Profile shared: ${res.userProfile.displayName || "unknown"}`;
  }

  openBtn.addEventListener("click", () => {
    // open Amazon profile page (user must be logged in and then click the "Share with store" panel we inject)
    chrome.tabs.create({ url: "https://www.amazon.com/gp/profile" });
  });

  [gCB, iCB, eCB].forEach(cb => {
    cb.addEventListener("change", async () => {
      const { settings = {} } = await chrome.storage.local.get("settings");
      settings.useGender = gCB.checked;
      settings.useIncome = iCB.checked;
      settings.useEthnicity = eCB.checked;
      chrome.storage.local.set({ settings });
    });
  });
});

